//! `cargo xtask fixtures [--check]`: the committed generated fixtures (ARCHITECTURE §A.9,
//! "Fixtures policy").
//!
//! Two groups of files are generated by `folioxide-testkit`, each into its own directory under
//! `fixtures/` with its own table in `fixtures/README.md` (between `BEGIN GENERATED` and
//! `END GENERATED` marker lines):
//!
//! - `fixtures/syntax/`: `folioxide_testkit::fixtures::syntax::all()`, the M1 store fixtures;
//! - `fixtures/hostile/`: `folioxide_testkit::fixtures::hostile::seeds()`, small instances of
//!   the resource-exhaustion shapes, committed so that the fuzz corpora (the nightly fuzz
//!   workflow seeds from `fixtures/`) start from them.
//!
//! Without `--check`, writes every generated file to `fixtures/<group>/<name>.pdf` (only files
//! whose bytes changed are rewritten), removes `*.pdf` files there that no generator produces
//! any more, and regenerates each group's README table.
//!
//! With `--check`, changes nothing and fails (exit 1) when a committed file is missing, differs
//! from the generated bytes or is stale, when a README table is out of date, or when a fixture
//! is not under 200 KB. Generation is deterministic, so a clean checkout always passes.
//!
//! `fixtures/qpdf/` is written by qpdf, through pikepdf in the oracle venv: the script
//! `tools/fixtures/qpdf.py` writes it, or checks it with `--check` (ARCHITECTURE §A.9:
//! `tools/fixtures/*.py` make the fixtures that need pikepdf). This task runs those scripts too
//! when `.venv` exists, in the same mode; without the venv (or with other pikepdf/libqpdf
//! versions than the committed files were written with) it says it skipped them, and the oracle
//! self-tests in CI check them.

use std::collections::BTreeMap;
use std::fs;
use std::io;
use std::path::Path;
use std::process::Command;

use folioxide_testkit::fixtures::{hostile, syntax};

use crate::{Outcome, display_command, oracle};

/// The fixture directories written by `tools/fixtures/<dir>.py` (pikepdf, in the oracle venv).
const SCRIPT_GROUPS: [&str; 1] = ["qpdf"];

/// Committed fixtures must stay under this size (CLAUDE.md, `fixtures/README.md`).
const MAX_FIXTURE_BYTES: usize = 200 * 1024;

/// The license of generated fixtures: the project's own (`fixtures/README.md`, "Generated by this
/// project"), taken from the workspace manifest so the table follows a license change.
const LICENSE: &str = env!("CARGO_PKG_LICENSE");

/// One directory of generated fixtures.
struct Group {
    /// The directory under `fixtures/`; also names the README markers.
    dir: &'static str,
    /// Every file as `(file name, bytes)`.
    generate: fn() -> Vec<(String, Vec<u8>)>,
    /// The rows of the README table: `(name, description)`; the file is `<dir>/<name>.pdf`.
    rows: fn() -> Vec<(&'static str, String)>,
}

/// The generated groups, in README order.
const GROUPS: [Group; 2] = [
    Group {
        dir: "syntax",
        generate: syntax_files,
        rows: syntax_rows,
    },
    Group {
        dir: "hostile",
        generate: hostile_files,
        rows: hostile_rows,
    },
];

fn syntax_files() -> Vec<(String, Vec<u8>)> {
    syntax::all()
        .into_iter()
        .map(|(name, bytes)| (format!("{name}.pdf"), bytes))
        .collect()
}

fn syntax_rows() -> Vec<(&'static str, String)> {
    syntax::infos()
        .iter()
        .map(|info| {
            let mut facts = vec![format!(
                "{} page{}",
                info.pages,
                if info.pages == 1 { "" } else { "s" }
            )];
            facts.push(
                if info.conforming {
                    "conforming"
                } else {
                    "not conforming"
                }
                .to_owned(),
            );
            if info.oracle_clean {
                facts.push("oracle-clean".to_owned());
            }
            (
                info.name,
                format!("{} ({})", info.description, facts.join(", ")),
            )
        })
        .collect()
}

fn hostile_files() -> Vec<(String, Vec<u8>)> {
    hostile::seeds()
        .into_iter()
        .map(|(name, bytes)| (format!("{name}.pdf"), bytes))
        .collect()
}

fn hostile_rows() -> Vec<(&'static str, String)> {
    hostile::seed_infos()
        .iter()
        .map(|info| (info.name, info.description.to_owned()))
        .collect()
}

impl Group {
    /// The line before the generated README table.
    fn begin(&self) -> String {
        format!(
            "<!-- BEGIN GENERATED fixtures/{}: `cargo xtask fixtures` rewrites this table -->",
            self.dir
        )
    }

    /// The line after the generated README table.
    fn end(&self) -> String {
        format!("<!-- END GENERATED fixtures/{} -->", self.dir)
    }

    /// The generated README table, markers included.
    fn readme_table(&self) -> String {
        let mut out = self.begin();
        out.push_str("\n| Files | What | Generator | License |\n|---|---|---|---|\n");
        for (name, description) in (self.rows)() {
            out.push_str(&format!(
                "| `{}/{name}.pdf` | {} | `cargo xtask fixtures` | {LICENSE} |\n",
                self.dir,
                description.replace('|', "\\|"),
            ));
        }
        out.push_str(&self.end());
        out
    }
}

/// How the committed files compare with the generated ones.
#[derive(Debug, Default, PartialEq, Eq)]
struct Diff {
    /// Generated but not committed.
    missing: Vec<String>,
    /// Committed with different bytes.
    changed: Vec<String>,
    /// Committed `*.pdf` files that nothing generates.
    stale: Vec<String>,
    /// Committed and identical.
    unchanged: usize,
}

impl Diff {
    fn is_clean(&self) -> bool {
        self.missing.is_empty() && self.changed.is_empty() && self.stale.is_empty()
    }
}

/// One group's generated files and how they compare with the committed ones.
struct Compared<'a> {
    group: &'a Group,
    generated: Vec<(String, Vec<u8>)>,
    diff: Diff,
}

/// Runs the task for the workspace at `root`.
pub(crate) fn run(root: &Path, check: bool) -> Outcome {
    let readme_path = root.join("fixtures").join("README.md");
    let readme = match fs::read_to_string(&readme_path) {
        Ok(readme) => readme,
        Err(err) => {
            eprintln!(
                "xtask: fixtures: cannot read {}: {err}",
                readme_path.display()
            );
            return Outcome::EnvError;
        }
    };
    let mut new_readme = readme.clone();
    let mut failures = Vec::new();
    let mut groups = Vec::new();
    for group in &GROUPS {
        let dir = root.join("fixtures").join(group.dir);
        let generated = (group.generate)();
        for (file, bytes) in &generated {
            if bytes.len() >= MAX_FIXTURE_BYTES {
                failures.push(format!(
                    "fixtures/{}/{file} is {} bytes; committed fixtures must be under \
                     {MAX_FIXTURE_BYTES}",
                    group.dir,
                    bytes.len()
                ));
            }
        }
        let existing = match read_pdfs(&dir) {
            Ok(existing) => existing,
            Err(err) => {
                eprintln!("xtask: fixtures: cannot read {}: {err}", dir.display());
                return Outcome::EnvError;
            }
        };
        new_readme = match splice_readme(&new_readme, group) {
            Ok(text) => text,
            Err(message) => {
                eprintln!("xtask: fixtures: {}: {message}", readme_path.display());
                return Outcome::EnvError;
            }
        };
        let diff = diff(&generated, &existing);
        groups.push(Compared {
            group,
            generated,
            diff,
        });
    }
    let total: usize = groups.iter().map(|c| c.generated.len()).sum();
    let dirs = GROUPS
        .iter()
        .map(|g| format!("fixtures/{}", g.dir))
        .collect::<Vec<_>>()
        .join(" and ");

    if check {
        for compared in &groups {
            let dir = compared.group.dir;
            let diff = &compared.diff;
            failures.extend(
                diff.missing
                    .iter()
                    .map(|f| format!("fixtures/{dir}/{f} is not committed")),
            );
            failures.extend(
                diff.changed
                    .iter()
                    .map(|f| format!("fixtures/{dir}/{f} differs from the generated bytes")),
            );
            failures.extend(
                diff.stale
                    .iter()
                    .map(|f| format!("fixtures/{dir}/{f} is not produced by any generator")),
            );
        }
        if new_readme != readme {
            failures.push("a generated table in fixtures/README.md is out of date".into());
        }
        if failures.is_empty() {
            println!("xtask: fixtures: {total} fixtures in {dirs} match their generators");
        }
    } else if groups.iter().all(|c| c.diff.is_clean()) && new_readme == readme {
        println!("xtask: fixtures: {total} fixtures in {dirs} are already up to date");
    } else {
        for compared in &groups {
            let dir = root.join("fixtures").join(compared.group.dir);
            if let Err(err) = write(&dir, &compared.generated, &compared.diff) {
                eprintln!("xtask: fixtures: {}: {err}", dir.display());
                return Outcome::EnvError;
            }
            println!(
                "xtask: fixtures: fixtures/{}: {} written, {} unchanged, {} removed",
                compared.group.dir,
                compared.diff.missing.len() + compared.diff.changed.len(),
                compared.diff.unchanged,
                compared.diff.stale.len(),
            );
        }
        if new_readme != readme {
            if let Err(err) = fs::write(&readme_path, &new_readme) {
                eprintln!("xtask: fixtures: {}: {err}", readme_path.display());
                return Outcome::EnvError;
            }
            println!("xtask: fixtures: README tables updated");
        }
    }

    for dir in SCRIPT_GROUPS {
        match run_script(root, dir, check) {
            ScriptResult::Pass => {}
            ScriptResult::Fail => failures.push(format!(
                "fixtures/{dir} does not match `tools/fixtures/{dir}.py` (see above)"
            )),
            ScriptResult::Skip(why) => println!("xtask: fixtures: SKIP fixtures/{dir}: {why}"),
        }
    }

    if failures.is_empty() {
        return Outcome::Success;
    }
    for failure in &failures {
        println!("xtask: fixtures: FAIL {failure}");
    }
    if check {
        println!("xtask: fixtures: run `cargo xtask fixtures` to regenerate");
    }
    Outcome::Failure
}

/// How a `tools/fixtures/*.py` script ended.
#[derive(Debug, PartialEq, Eq)]
enum ScriptResult {
    /// Exit 0: written, or the committed files match.
    Pass,
    /// Exit 1 (or a signal): the committed files differ, or the files could not be written.
    Fail,
    /// The script could not run here: no venv, or exit 2 (pikepdf or libqpdf versions other
    /// than the committed files were written with).
    Skip(String),
}

/// Runs `tools/fixtures/<dir>.py [--check]` with the venv's interpreter, output inherited.
fn run_script(root: &Path, dir: &str, check: bool) -> ScriptResult {
    let python = oracle::venv_python(root);
    if !python.is_file() {
        return ScriptResult::Skip(format!(
            "no oracle venv (run `bash tools/setup-venv.sh`, then `.venv/bin/python -I \
             tools/fixtures/{dir}.py --check`)"
        ));
    }
    let mut command = Command::new(&python);
    command.current_dir(root).arg("-I").arg(
        Path::new("tools")
            .join("fixtures")
            .join(format!("{dir}.py")),
    );
    if check {
        command.arg("--check");
    }
    let shown = display_command(&command);
    println!("xtask: fixtures: running `{shown}`");
    match command.status() {
        Ok(status) => script_result(status.code()),
        Err(err) => ScriptResult::Skip(format!("could not start `{shown}`: {err}")),
    }
}

/// The result for a script's exit code (`None` when it was killed by a signal).
fn script_result(code: Option<i32>) -> ScriptResult {
    match code {
        Some(0) => ScriptResult::Pass,
        Some(2) => ScriptResult::Skip(
            "the venv cannot reproduce these files (see above; `bash tools/setup-venv.sh` \
             installs the pinned versions)"
                .to_owned(),
        ),
        _ => ScriptResult::Fail,
    }
}

/// Writes missing and changed files and removes stale ones.
fn write(dir: &Path, generated: &[(String, Vec<u8>)], diff: &Diff) -> io::Result<()> {
    fs::create_dir_all(dir)?;
    for (file, bytes) in generated {
        if diff.missing.contains(file) || diff.changed.contains(file) {
            fs::write(dir.join(file), bytes)?;
        }
    }
    for file in &diff.stale {
        fs::remove_file(dir.join(file))?;
    }
    Ok(())
}

/// The `*.pdf` files directly in `dir` (none if it does not exist).
fn read_pdfs(dir: &Path) -> io::Result<BTreeMap<String, Vec<u8>>> {
    let mut files = BTreeMap::new();
    let entries = match fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(err) if err.kind() == io::ErrorKind::NotFound => return Ok(files),
        Err(err) => return Err(err),
    };
    for entry in entries {
        let entry = entry?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.ends_with(".pdf") && entry.file_type()?.is_file() {
            files.insert(name, fs::read(entry.path())?);
        }
    }
    Ok(files)
}

/// Compares generated files with committed ones.
fn diff(generated: &[(String, Vec<u8>)], existing: &BTreeMap<String, Vec<u8>>) -> Diff {
    let mut diff = Diff::default();
    for (file, bytes) in generated {
        match existing.get(file) {
            None => diff.missing.push(file.clone()),
            Some(old) if old != bytes => diff.changed.push(file.clone()),
            Some(_) => diff.unchanged += 1,
        }
    }
    diff.stale = existing
        .keys()
        .filter(|file| !generated.iter().any(|(name, _)| name == *file))
        .cloned()
        .collect();
    diff
}

/// Replaces the text from `group`'s begin marker to its end marker (inclusive) with its
/// generated table.
fn splice_readme(readme: &str, group: &Group) -> Result<String, String> {
    splice(readme, &group.begin(), &group.end(), &group.readme_table())
}

/// Replaces the text from `begin` to `end` (inclusive) with `table`.
fn splice(readme: &str, begin: &str, end: &str, table: &str) -> Result<String, String> {
    let (before, rest) = readme
        .split_once(begin)
        .ok_or_else(|| format!("missing the marker line {begin:?}"))?;
    let (_, after) = rest
        .split_once(end)
        .ok_or_else(|| format!("missing the marker line {end:?}"))?;
    Ok(format!("{before}{table}{after}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn files(list: &[(&str, &[u8])]) -> Vec<(String, Vec<u8>)> {
        list.iter()
            .map(|(name, bytes)| ((*name).to_owned(), bytes.to_vec()))
            .collect()
    }

    #[test]
    fn diff_classifies_files() {
        let generated = files(&[("a.pdf", b"A"), ("b.pdf", b"B"), ("c.pdf", b"C")]);
        let existing: BTreeMap<String, Vec<u8>> =
            files(&[("a.pdf", b"A"), ("b.pdf", b"b"), ("old.pdf", b"x")])
                .into_iter()
                .collect();
        let d = diff(&generated, &existing);
        assert_eq!(
            d,
            Diff {
                missing: vec!["c.pdf".into()],
                changed: vec!["b.pdf".into()],
                stale: vec!["old.pdf".into()],
                unchanged: 1,
            }
        );
        assert!(!d.is_clean());
        let same: BTreeMap<String, Vec<u8>> = generated.iter().cloned().collect();
        assert!(diff(&generated, &same).is_clean());
    }

    #[test]
    fn splice_replaces_only_the_marked_table() {
        let (begin, end) = ("<!-- BEGIN x -->", "<!-- END x -->");
        let readme = format!("intro\n{begin}\nold rows\n{end}\noutro\n");
        let table = format!("{begin}\nnew\n{end}");
        assert_eq!(
            splice(&readme, begin, end, &table).unwrap(),
            format!("intro\n{begin}\nnew\n{end}\noutro\n")
        );
        assert!(splice("no markers", begin, end, &table).is_err());
        assert!(splice(&format!("{begin}\n"), begin, end, &table).is_err());
    }

    #[test]
    fn script_exit_codes() {
        assert_eq!(script_result(Some(0)), ScriptResult::Pass);
        assert_eq!(script_result(Some(1)), ScriptResult::Fail);
        assert_eq!(script_result(None), ScriptResult::Fail);
        assert!(matches!(script_result(Some(2)), ScriptResult::Skip(_)));
        // Without a venv nothing runs.
        let no_venv = std::env::temp_dir().join("folioxide-xtask-no-such-root");
        assert!(matches!(
            run_script(&no_venv, "qpdf", true),
            ScriptResult::Skip(why) if why.contains("no oracle venv")
        ));
        for dir in SCRIPT_GROUPS {
            let root = crate::workspace_root();
            assert!(
                root.join("tools")
                    .join("fixtures")
                    .join(format!("{dir}.py"))
                    .is_file()
            );
            assert!(root.join("fixtures").join(dir).is_dir());
            assert!(GROUPS.iter().all(|g| g.dir != dir));
        }
    }

    #[test]
    fn markers_keep_their_text() {
        // The README has these exact lines; changing them orphans the committed tables.
        assert_eq!(
            GROUPS[0].begin(),
            "<!-- BEGIN GENERATED fixtures/syntax: `cargo xtask fixtures` rewrites this table -->"
        );
        assert_eq!(GROUPS[0].end(), "<!-- END GENERATED fixtures/syntax -->");
        assert_eq!(GROUPS[1].end(), "<!-- END GENERATED fixtures/hostile -->");
    }

    #[test]
    fn readme_tables_list_every_fixture() {
        for group in &GROUPS {
            let table = group.readme_table();
            for (file, _) in (group.generate)() {
                assert!(
                    table.contains(&format!("| `{}/{file}` |", group.dir)),
                    "{}/{file}",
                    group.dir
                );
            }
            assert!(table.starts_with(&group.begin()));
            assert!(table.ends_with(&group.end()));
        }
    }

    #[test]
    fn committed_fixtures_are_up_to_date() {
        // The same comparison as `cargo xtask fixtures --check`, so `cargo test` catches drift.
        let root = crate::workspace_root();
        let readme = fs::read_to_string(root.join("fixtures").join("README.md")).unwrap();
        for group in &GROUPS {
            let generated = (group.generate)();
            let existing = read_pdfs(&root.join("fixtures").join(group.dir)).unwrap();
            let d = diff(&generated, &existing);
            assert!(
                d.is_clean(),
                "fixtures/{}: run `cargo xtask fixtures`: {d:?}",
                group.dir
            );
            assert!(generated.iter().all(|(_, b)| b.len() < MAX_FIXTURE_BYTES));
            assert_eq!(
                splice_readme(&readme, group).unwrap(),
                readme,
                "{}",
                group.dir
            );
        }
    }
}
